import {assistantEndpoint} from './ai-config.js?v=17';
export class LabAssistant{
 constructor({getContext,endpoint=assistantEndpoint,document=globalThis.document,fetcher=globalThis.fetch}={}){
  Object.assign(this,{document,getContext,endpoint,fetcher,threads:new Map(),busy:false});
  this.root=document.createElement('aside');this.root.id='aiAssistant';this.root.className='ai-assistant';this.root.hidden=true;this.root.setAttribute('aria-labelledby','aiTitle');
  this.root.innerHTML='<div class="ai-head"><h2 id="aiTitle">Trợ lý Vật lí</h2><button type="button" data-ai="close" aria-label="Đóng trợ lý">×</button></div><p class="ai-status" role="status" aria-live="polite"></p><div class="ai-messages" role="log" aria-label="Hội thoại"></div><form class="ai-compose"><label for="aiQuestion">Câu hỏi của bạn</label><textarea id="aiQuestion" maxlength="6000" placeholder="Ví dụ: Vì sao đồ thị có dạng này?"></textarea><label class="ai-consent"><input type="checkbox" id="aiContext">Gửi kèm thông số và tối đa 12 dòng đo của bài đang mở</label><details><summary>Xem dữ liệu gửi kèm</summary><pre class="ai-context"></pre></details><div class="ai-actions"><button type="button" data-ai="clear">Hội thoại mới</button><button type="button" data-ai="cancel" hidden>Dừng</button><button type="submit">Gửi câu hỏi ↑</button></div></form>';
  document.body.append(this.root);this.q=s=>this.root.querySelector(s);this.status=this.q('.ai-status');this.form=this.q('form');this.input=this.q('textarea');this.submit=this.q('[type=submit]');
  this.openButton=document.querySelector('#openAssistant');this.openButton?.addEventListener('click',()=>this.open());
  this.q('[data-ai=close]').addEventListener('click',()=>this.close());this.q('[data-ai=cancel]').addEventListener('click',()=>this.controller?.abort());this.q('[data-ai=clear]').addEventListener('click',()=>{this.controller?.abort();this.threads.delete(this.key());this.render();});
  this.form.addEventListener('submit',e=>{e.preventDefault();this.send();});this.root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();this.close();}});
  this.render();
 }
 refreshContext(){if(this.root.hidden)return;const key=this.key();if(this.currentKey!==key)this.render();else this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{},null,2);}
 key(){return this.getContext?.()?.id||'library';}
 thread(key=this.key()){if(!this.threads.has(key))this.threads.set(key,[]);return this.threads.get(key);}
 open(){this.root.hidden=false;this.openButton?.setAttribute('aria-expanded','true');this.render();this.input.focus();}
 close(){this.root.hidden=true;this.openButton?.setAttribute('aria-expanded','false');this.openButton?.focus();}
 render(){this.currentKey=this.key();const list=this.q('.ai-messages');list.replaceChildren();for(const message of this.thread()){const el=this.document.createElement('div');el.className='ai-message';el.dataset.role=message.role;const label=this.document.createElement('b');label.textContent=message.role==='user'?'Bạn':'Trợ lý AI';el.append(label,this.document.createTextNode(message.content));list.append(el);}list.scrollTop=list.scrollHeight;this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{page:'Thư viện thí nghiệm'},null,2);this.submit.disabled=this.busy||!this.endpoint;this.q('[data-ai=cancel]').hidden=!this.busy;this.q('[data-ai=clear]').disabled=this.busy;this.status.textContent=this.busy?'Đang trả lời…':this.endpoint?'AI có thể nhầm. Hãy đối chiếu công thức và số liệu.':'Trợ lý AI chưa được kết nối. Cần cấu hình máy chủ để gửi câu hỏi.';}
 async send(){const question=this.input.value.trim();if(!question||this.busy||!this.endpoint)return;const key=this.key(),thread=this.thread(key),context=this.q('#aiContext').checked?(this.getContext?.()||null):null,history=thread.slice(-10).map(m=>({...m}));this.busy=true;this.controller=new AbortController();this.render();const timeout=setTimeout(()=>this.controller?.abort(),45000);
  try{const response=await this.fetcher(this.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history,context}),signal:this.controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});const data=await response.json();if(!response.ok)throw Error(data.error||'Chưa gửi được câu hỏi. Vui lòng thử lại.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('Máy chủ chưa trả về câu trả lời.');thread.push({role:'user',content:question},{role:'assistant',content:data.answer.slice(0,24000)});if(thread.length>40)thread.splice(0,thread.length-40);if(this.key()===key)this.input.value='';this.busy=false;this.render();if(this.key()!==key)this.status.textContent='Câu trả lời đã lưu trong hội thoại của bài trước.';
  }catch(error){this.busy=false;this.render();this.status.textContent=error.name==='AbortError'?'Đã dừng yêu cầu. Câu hỏi vẫn được giữ.':error.message||'Không kết nối được trợ lý.';}
  finally{clearTimeout(timeout);this.controller=null;}
 }
}
